-- R2, information preservation: the original graph's facts, recovered from its triples alone. For each class
-- the set of its vertices; for each column the set of (subject, value, datatype); for each relation the set of
-- (source subject, target subject). Each statement counts the differences between the two, and must count 0.
-- The fixture is admissible (A1-A7): its subjects are absolute IRIs, unique across the types, its edges are distinct pairs.
SELECT 'class Person' AS what, (SELECT count(*) FROM ((SELECT subject FROM g."Person") EXCEPT (SELECT s_value FROM g_triples WHERE p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND o_value = 'https://example.org/Person'))) + (SELECT count(*) FROM ((SELECT s_value FROM g_triples WHERE p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND o_value = 'https://example.org/Person') EXCEPT (SELECT subject FROM g."Person"))) AS n;
SELECT 'class Order' AS what, (SELECT count(*) FROM ((SELECT subject FROM g."Order") EXCEPT (SELECT s_value FROM g_triples WHERE p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND o_value = 'https://example.org/Order'))) + (SELECT count(*) FROM ((SELECT s_value FROM g_triples WHERE p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND o_value = 'https://example.org/Order') EXCEPT (SELECT subject FROM g."Order"))) AS n;
SELECT 'class Tag' AS what, (SELECT count(*) FROM ((SELECT subject FROM g."Tag") EXCEPT (SELECT s_value FROM g_triples WHERE p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND o_value = 'https://example.org/Tag'))) + (SELECT count(*) FROM ((SELECT s_value FROM g_triples WHERE p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND o_value = 'https://example.org/Tag') EXCEPT (SELECT subject FROM g."Tag"))) AS n;
SELECT 'column Person.birth_year' AS what, (SELECT count(*) FROM ((SELECT subject, CAST(birth_year AS VARCHAR), 'http://www.w3.org/2001/XMLSchema#gYear' FROM g."Person" WHERE birth_year IS NOT NULL) EXCEPT (SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/birthYear'))) + (SELECT count(*) FROM ((SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/birthYear') EXCEPT (SELECT subject, CAST(birth_year AS VARCHAR), 'http://www.w3.org/2001/XMLSchema#gYear' FROM g."Person" WHERE birth_year IS NOT NULL))) AS n;
SELECT 'column Person.postcode' AS what, (SELECT count(*) FROM ((SELECT subject, CAST(postcode AS VARCHAR), 'http://www.w3.org/2001/XMLSchema#string' FROM g."Person" WHERE postcode IS NOT NULL) EXCEPT (SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/postcode'))) + (SELECT count(*) FROM ((SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/postcode') EXCEPT (SELECT subject, CAST(postcode AS VARCHAR), 'http://www.w3.org/2001/XMLSchema#string' FROM g."Person" WHERE postcode IS NOT NULL))) AS n;
SELECT 'column Order.amount' AS what, (SELECT count(*) FROM ((SELECT subject, CAST(amount AS VARCHAR), 'http://www.w3.org/2001/XMLSchema#decimal' FROM g."Order" WHERE amount IS NOT NULL) EXCEPT (SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/amount'))) + (SELECT count(*) FROM ((SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/amount') EXCEPT (SELECT subject, CAST(amount AS VARCHAR), 'http://www.w3.org/2001/XMLSchema#decimal' FROM g."Order" WHERE amount IS NOT NULL))) AS n;
SELECT 'column Tag.name' AS what, (SELECT count(*) FROM ((SELECT subject, CAST(name AS VARCHAR), 'http://www.w3.org/2001/XMLSchema#string' FROM g."Tag" WHERE name IS NOT NULL) EXCEPT (SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/name'))) + (SELECT count(*) FROM ((SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/name') EXCEPT (SELECT subject, CAST(name AS VARCHAR), 'http://www.w3.org/2001/XMLSchema#string' FROM g."Tag" WHERE name IS NOT NULL))) AS n;
SELECT 'column Person.nickname' AS what, (SELECT count(*) FROM ((SELECT s.subject, e.nickname, 'http://www.w3.org/2001/XMLSchema#string' FROM g."Person_nickname" e JOIN g."Person" s ON e.src = s.dense_id) EXCEPT (SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/nickname'))) + (SELECT count(*) FROM ((SELECT s_value, o_value, o_datatype FROM g_triples WHERE p = 'https://example.org/nickname') EXCEPT (SELECT s.subject, e.nickname, 'http://www.w3.org/2001/XMLSchema#string' FROM g."Person_nickname" e JOIN g."Person" s ON e.src = s.dense_id))) AS n;
SELECT 'relation knows' AS what, (SELECT count(*) FROM ((SELECT s.subject, d.subject FROM g."Person_knows_Person" e JOIN g."Person" s ON e.src = s.dense_id JOIN g."Person" d ON e.dst = d.dense_id) EXCEPT (SELECT s_value, o_value FROM g_triples WHERE p = 'https://example.org/knows'))) + (SELECT count(*) FROM ((SELECT s_value, o_value FROM g_triples WHERE p = 'https://example.org/knows') EXCEPT (SELECT s.subject, d.subject FROM g."Person_knows_Person" e JOIN g."Person" s ON e.src = s.dense_id JOIN g."Person" d ON e.dst = d.dense_id))) AS n;
SELECT 'relation placedBy' AS what, (SELECT count(*) FROM ((SELECT s.subject, d.subject FROM g."Order_placedBy_Person" e JOIN g."Order" s ON e.src = s.dense_id JOIN g."Person" d ON e.dst = d.dense_id) EXCEPT (SELECT s_value, o_value FROM g_triples WHERE p = 'https://example.org/placedBy'))) + (SELECT count(*) FROM ((SELECT s_value, o_value FROM g_triples WHERE p = 'https://example.org/placedBy') EXCEPT (SELECT s.subject, d.subject FROM g."Order_placedBy_Person" e JOIN g."Order" s ON e.src = s.dense_id JOIN g."Person" d ON e.dst = d.dense_id))) AS n;
SELECT 'relation tagged' AS what, (SELECT count(*) FROM ((SELECT s.subject, d.subject FROM g."Person_tagged_Tag" e JOIN g."Person" s ON e.src = s.dense_id JOIN g."Tag" d ON e.dst = d.dense_id) EXCEPT (SELECT s_value, o_value FROM g_triples WHERE p = 'https://example.org/tagged'))) + (SELECT count(*) FROM ((SELECT s_value, o_value FROM g_triples WHERE p = 'https://example.org/tagged') EXCEPT (SELECT s.subject, d.subject FROM g."Person_tagged_Tag" e JOIN g."Person" s ON e.src = s.dense_id JOIN g."Tag" d ON e.dst = d.dense_id))) AS n;
-- A5: within a relation the (source, destination) pairs are distinct.
SELECT 'edge-unique knows' AS what, (SELECT count(*) FROM g."Person_knows_Person") - (SELECT count(*) FROM (SELECT DISTINCT src, dst FROM g."Person_knows_Person")) AS n;
SELECT 'edge-unique placedBy' AS what, (SELECT count(*) FROM g."Order_placedBy_Person") - (SELECT count(*) FROM (SELECT DISTINCT src, dst FROM g."Order_placedBy_Person")) AS n;
SELECT 'edge-unique tagged' AS what, (SELECT count(*) FROM g."Person_tagged_Tag") - (SELECT count(*) FROM (SELECT DISTINCT src, dst FROM g."Person_tagged_Tag")) AS n;
-- A1: no subject is the subject of two vertices, of the same type or another.
SELECT 'subjects distinct' AS what, (SELECT count(*) FROM (SELECT subject FROM g."Person" UNION ALL SELECT subject FROM g."Order" UNION ALL SELECT subject FROM g."Tag")) - (SELECT count(DISTINCT subject) FROM (SELECT subject FROM g."Person" UNION ALL SELECT subject FROM g."Order" UNION ALL SELECT subject FROM g."Tag")) AS n;
